CREATE TABLE writer_lease(id INTEGER PRIMARY KEY CHECK(id=1),token TEXT NOT NULL,host TEXT NOT NULL,pid INTEGER NOT NULL,started_at TEXT NOT NULL);
CREATE TABLE writer_audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,event TEXT NOT NULL,token TEXT,detail TEXT NOT NULL,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE external_ops(op_key TEXT PRIMARY KEY,request_id TEXT NOT NULL,method TEXT NOT NULL,target TEXT NOT NULL,payload_hash TEXT NOT NULL,status TEXT NOT NULL,result_id TEXT,error TEXT,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,approval_id TEXT,doc_key TEXT);
CREATE TABLE approval_requests(request_id TEXT PRIMARY KEY,scope TEXT NOT NULL,payload_hash TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE exceptional_post_retries(original_op_key TEXT PRIMARY KEY,retry_op_key TEXT UNIQUE NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,approval_id TEXT UNIQUE NOT NULL,preflight_sha256 TEXT NOT NULL,status TEXT NOT NULL,freee_id TEXT,sync_status TEXT NOT NULL DEFAULT 'not_started',at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE corrected_post_retries(root_op_key TEXT PRIMARY KEY,prior_retry_op_key TEXT NOT NULL,retry_op_key TEXT UNIQUE NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,approval_id TEXT UNIQUE NOT NULL,preflight_sha256 TEXT NOT NULL,status TEXT NOT NULL,freee_id TEXT,sync_status TEXT NOT NULL DEFAULT 'not_started',at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_post_retries(original_op_key TEXT PRIMARY KEY,retry_op_key TEXT UNIQUE NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,approval_id TEXT UNIQUE NOT NULL,preflight_sha256 TEXT NOT NULL,status TEXT NOT NULL,freee_id TEXT,sync_status TEXT NOT NULL DEFAULT 'not_started',at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notion_test_approvals(approval_id TEXT PRIMARY KEY,generation_request_id TEXT NOT NULL,header_database TEXT NOT NULL,line_database TEXT NOT NULL,scope TEXT NOT NULL,plan_hash TEXT NOT NULL,max_pages INTEGER NOT NULL,approver TEXT NOT NULL,approved_at TEXT NOT NULL,state TEXT NOT NULL,result_json TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notion_host_approvals(approval_id TEXT PRIMARY KEY,generation_request_id TEXT NOT NULL,header_database TEXT NOT NULL,line_database TEXT NOT NULL,scope TEXT NOT NULL,plan_hash TEXT NOT NULL,max_pages INTEGER NOT NULL,approver_id TEXT NOT NULL,approver_label TEXT NOT NULL,host_context_id TEXT NOT NULL,approved_at TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL,result_json TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
